  const doHwUpload = useCallback(async (file: File, uploadType: 'module' | 'reading', courseCode: string, courseName: string, week: number, courseHexColor: string, semKey?: string) => {
    const stateKey = `${courseCode}-${week}-${uploadType}`;
    setHwUploadingState(prev => ({ ...prev, [stateKey]: true }));
    try {
      const semKeyToStartDate: Record<string, string> = {
        'ss2025': '2025-05-05', 'f2025': '2025-09-08', 'w2026': '2026-01-12',
        'ss2026': '2026-05-04', 'f2026': '2026-09-14', 'w2027': '2027-01-11',
        'ss2027': '2027-05-03', 'f2027': '2027-09-13', 'w2028': '2028-01-10',
        'ss2028': '2028-05-01', 'f2028': '2028-09-11', 'w2029': '2029-01-15',
      };
      const ss = semesterSettingsRef.current;
      let semStartDate: Date;
      let rwStart: Date | null = ss?.readingWeekStart ? new Date(ss.readingWeekStart) : null;
      if (semKey && semKeyToStartDate[semKey]) {
        semStartDate = new Date(semKeyToStartDate[semKey] + 'T00:00:00');
        const allSems = allSemesterSettingsRef.current;
        if (allSems) {
          const semKeyToType: Record<string, string> = { 'w': 'winter', 'ss': 'spring_summer', 'f': 'fall' };
          const prefix = semKey.replace(/\d+$/, '');
          const yearStr = semKey.replace(/^\D+/, '');
          const matchSem = allSems.find((s: any) => {
            const sy = s.semesterName?.match(/\d{4}/)?.[0] || '';
            return s.semesterType === semKeyToType[prefix] && sy === yearStr;
          });
          if (matchSem?.readingWeekStart) rwStart = new Date(matchSem.readingWeekStart);
        }
      } else {
        semStartDate = new Date(ss?.semesterStartDate || Date.now());
      }
      const wd = getWeekDates(week, semStartDate, rwStart);
      const ws = new Date(wd.start);
      const we = new Date(wd.end);
      const mos = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
      const s1 = `${mos[ws.getMonth()]} ${ws.getDate()}`;
      const s2 = ws.getMonth() === we.getMonth() ? `${we.getDate()}` : `${mos[we.getMonth()]} ${we.getDate()}`;
      const dr = `${s1}-${s2}`;
      const codeClean = courseCode.replace(/\s/g, '');

      let semYear = '';
      let semTypeHeader = '';
      let spsuTerm = '';
      let moduleFolderOverride = '';
      let readingFolderOverride = '';
      if (semKey) {
        const yearStr = semKey.replace(/^\D+/, '');
        semYear = yearStr;
        const prefix = semKey.replace(/\d+$/, '');
        semTypeHeader = prefix === 'ss' ? 'spring_summer' : prefix === 'f' ? 'fall' : 'winter';
        const allSems = allSemesterSettingsRef.current;
        if (allSems) {
          const semKeyToType: Record<string, string> = { 'w': 'winter', 'ss': 'spring_summer', 'f': 'fall' };
          const matchSem = allSems.find((s: any) => {
            const sy = s.semesterName?.match(/\d{4}/)?.[0] || '';
            return s.semesterType === semKeyToType[prefix] && sy === yearStr;
          });
          if (matchSem) {
            const cc = codeClean.toUpperCase();
            for (let i = 1; i <= 3; i++) {
              const dbCode = ((matchSem as any)[`course${i}Code`] || '').replace(/\s/g, '').toUpperCase();
              const tdbMatch = cc.match(/^TBD_SLOT(\d+)$/);
              const lookupCode = tdbMatch ? `TBD${tdbMatch[1]}` : cc;
              if (dbCode === lookupCode || dbCode === cc) {
                spsuTerm = ((matchSem as any)[`course${i}SpringSummerTerm`] || 'full').toLowerCase();
                moduleFolderOverride = (matchSem as any)[`course${i}ModuleFolder`] || '';
                readingFolderOverride = (matchSem as any)[`course${i}ReadingFolder`] || '';
                break;
              }
            }
          }
        }
      }

      const resp = await fetch('/api/course-week-upload', {
        method: 'POST',
        headers: {
          'Content-Type': file.type || 'application/pdf',
          'x-course-code': codeClean,
          'x-course-name': courseName.split(' - ').slice(1).join(' - ') || '',
          'x-week-num': String(week),
          'x-upload-type': uploadType,
          'x-week-date-range': dr,
          'x-file-name': file.name,
          'x-semester-year': semYear,
          'x-semester-type': semTypeHeader,
          'x-spsu-term': spsuTerm,
          'x-module-folder': moduleFolderOverride,
          'x-reading-folder': readingFolderOverride,
        },
        body: file,
      });
      const result = await resp.json();
      if (resp.ok && result.success) {
        toast({ title: `${uploadType === 'module' ? 'Module' : 'Reading'} uploaded`, description: `${file.name} saved and queued for TTS` });
        queryClient.invalidateQueries({ queryKey: ['/api/files'] });
        setBookAnimState({
          isOpen: true,
          courseCode: codeClean,
          title: file.name,
          color: courseHexColor,
          onDone: () => {
            setBookAnimState(null);
            if (result.fileId) {
              setBookReaderOverlay({ url: `/pdf-reader/${result.fileId}?autoplay=1`, courseCode: codeClean, title: file.name, color: courseHexColor });
            }
          },
        });
      } else {
        toast({ title: 'Upload failed', description: result.error || 'Unknown error', variant: 'destructive' });
      }
    } catch (err: any) {
      toast({ title: 'Upload error', description: err.message, variant: 'destructive' });
    } finally {
      setHwUploadingState(prev => ({ ...prev, [stateKey]: false }));
    }
  }, []);
  const layoutDefaultsLoadedRef = useRef(false);
  const serverLayoutLoadedRef = useRef(false);
  useEffect(() => {
    if (layoutDefaultsLoadedRef.current || serverLayoutLoadedRef.current) return;
    serverLayoutLoadedRef.current = true;
    const screenWidth = window.screen.width;
    const screenHeight = window.screen.height;
    const pixelRatio = window.devicePixelRatio || 1;
    const did = `device_${screenWidth}x${screenHeight}@${pixelRatio}`;
    fetch(`/api/app-state/calendarLayout_${did}`)
      .then(r => r.json())
      .then(data => {
        if (!data.value || layoutDefaultsLoadedRef.current) {
          layoutDefaultsLoadedRef.current = true;
          return;
        }
        try {
          const saved = JSON.parse(data.value);
          const minH = 200; const maxH = window.innerHeight - 100;
          if (saved.calendarHeight) {
            const v = Math.min(Math.max(saved.calendarHeight, minH), maxH);
            setCalendarHeight(v);
            localStorage.setItem('calendarHeight', String(v));
            localStorage.setItem(`calendarHeight_${did}`, String(v));
          }
          if (saved.calendarReduction !== undefined) {
            const minReduction = 260;
            const safeReduction = saved.calendarReduction < minReduction ? minReduction : saved.calendarReduction;
            calendarReductionUserSetRef.current = true;
            setCalendarReduction(safeReduction);
            setCalendarReductionUserSet(true);
            localStorage.setItem('calendarReduction', String(safeReduction));
            localStorage.setItem(`calendarReduction_${did}`, String(safeReduction));
            localStorage.setItem('calendarReductionUserSet', '1');
          }
          if (saved.gridSizes) {
            setGridSizes(saved.gridSizes);
            localStorage.setItem('gridSizes', JSON.stringify(saved.gridSizes));
            localStorage.setItem(`gridSizes_${did}`, JSON.stringify(saved.gridSizes));
          }
          if (saved.hwGroupBarWidth) {
            setHwGroupBarWidth(saved.hwGroupBarWidth);
            localStorage.setItem('hwGroupBarWidth', String(saved.hwGroupBarWidth));
            localStorage.setItem(`hwGroupBarWidth_${did}`, String(saved.hwGroupBarWidth));
          }
          layoutDefaultsLoadedRef.current = true;
          console.log('[Layout] Loaded calendar defaults from server for device', did);
        } catch (e) { layoutDefaultsLoadedRef.current = true; }
      })
      .catch(() => {
        fetch('/api/app-state/calendarLayoutDefaults')
          .then(r => r.json())
          .then(data => {
            if (!data.value || layoutDefaultsLoadedRef.current) {
              layoutDefaultsLoadedRef.current = true;
              return;
            }
            try {
              const saved = JSON.parse(data.value);
              const minH = 200; const maxH = window.innerHeight - 100;
              if (saved.calendarHeight) {
                const v = Math.min(Math.max(saved.calendarHeight, minH), maxH);
                setCalendarHeight(v);
                localStorage.setItem('calendarHeight', String(v));
              }
              if (saved.calendarReduction !== undefined) {
                const minReduction = 260;
                const safeReduction = saved.calendarReduction < minReduction ? minReduction : saved.calendarReduction;
                calendarReductionUserSetRef.current = true;
                setCalendarReduction(safeReduction);
                setCalendarReductionUserSet(true);
                localStorage.setItem('calendarReduction', String(safeReduction));
                localStorage.setItem('calendarReductionUserSet', '1');
              }
              if (saved.gridSizes) {
                setGridSizes(saved.gridSizes);
                localStorage.setItem('gridSizes', JSON.stringify(saved.gridSizes));
              }
              if (saved.hwGroupBarWidth) {
                setHwGroupBarWidth(saved.hwGroupBarWidth);
                localStorage.setItem('hwGroupBarWidth', String(saved.hwGroupBarWidth));
              }
              layoutDefaultsLoadedRef.current = true;
              console.log('[Layout] Loaded calendar defaults from server (generic)');
            } catch (e) { layoutDefaultsLoadedRef.current = true; }
          })
          .catch(() => { layoutDefaultsLoadedRef.current = true; });
      });
  }, []);
  const [calendarHeight, setCalendarHeight] = useState(() => {
    const defaultHeight = window.innerHeight - 47;
    const minHeight = 200;
    const maxHeight = window.innerHeight - 100;
    const screenWidth = window.screen.width;
    const screenHeight = window.screen.height;
    const pixelRatio = window.devicePixelRatio || 1;
    const deviceId = `device_${screenWidth}x${screenHeight}@${pixelRatio}`;
    const deviceSaved = localStorage.getItem(`calendarHeight_${deviceId}`);
    if (deviceSaved) {
      const val = parseInt(deviceSaved, 10);
      if (!isNaN(val) && val >= minHeight) { layoutDefaultsLoadedRef.current = true; return Math.min(val, maxHeight); }
    }
    const saved = localStorage.getItem('calendarHeight');
    if (saved) {
      const val = parseInt(saved, 10);
      if (!isNaN(val) && val >= minHeight) { layoutDefaultsLoadedRef.current = true; return Math.min(val, maxHeight); }
    }
    return defaultHeight;
  });
  const [isResizing, setIsResizing] = useState(false);
  const resizeRef = useRef<{ startY: number; startHeight: number } | null>(null);
  const [doTodayBounce, setDoTodayBounce] = useState(false);
