  const [isPillMenuOpen, setIsPillMenuOpen] = useState(false);
  const [sidePillIdle, setSidePillIdle] = useState(false);
  const pillMenuTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const sidePillRef = useRef<HTMLDivElement>(null);
  const [sidePillMounted, setSidePillMounted] = useState(false);
  const sidePillSlideOffset = useRef(60);
  const openSidePill = useCallback(() => {
    const el = sidePillRef.current;
    if (el && sidePillIdle) {
      const computed = getComputedStyle(el);
      const matrix = new DOMMatrixReadOnly(computed.transform);
      const currentY = matrix.m42;
      el.style.transition = 'none';
      el.style.transform = `translateX(-50%) translateY(${currentY}px)`;
      setSidePillIdle(false);
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          el.style.transition = 'transform 0.3s ease-in-out';
          el.style.transform = 'translateX(-50%) translateY(0px)';
          startTransition(() => setIsPillMenuOpen(true));
        });
      });
    } else {
      setSidePillIdle(false);
      startTransition(() => setIsPillMenuOpen(true));
    }
  }, [sidePillIdle]);
  const closeSidePill = useCallback(() => {
    startTransition(() => setIsPillMenuOpen(false));
  }, []);
  useEffect(() => {
    if (!isPillMenuOpen && sidePillMounted) {
      const el = sidePillRef.current;
      if (el) {
        const onEnd = () => {
          setSidePillIdle(true);
          el.removeEventListener('transitionend', onEnd);
        };
        el.addEventListener('transitionend', onEnd);
        return () => el.removeEventListener('transitionend', onEnd);
      }
    }
  }, [isPillMenuOpen, sidePillMounted]);
  useEffect(() => {
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        setSidePillMounted(true);
        startTransition(() => setIsPillMenuOpen(true));
      });
    });
    const sideTimeout = setTimeout(() => {
      closeSidePill();
    }, 2200);
    return () => clearTimeout(sideTimeout);
  }, []);
  const [isTopPillOpen, setIsTopPillOpenState] = useState(false);
  const isTopPillOpenRef = useRef(false);
  const setIsTopPillOpen = useCallback((val: boolean) => {
    if (isTopPillOpenRef.current === val) return;
    isTopPillOpenRef.current = val;
    setIsTopPillOpenState(val);
    document.querySelectorAll<HTMLElement>('[data-tpo]').forEach(el => {
      el.style.opacity = val ? '0' : (el.dataset.tpoOpacity || '1');
      el.style.pointerEvents = val ? 'none' : 'auto';
      el.style.transition = val ? 'opacity 0.3s ease-in-out' : 'opacity 0.1s ease-in-out';
    });
  }, []);
  const pillFlyoutWasOpenRef = useRef(false);
  const [topPillUndocked, setTopPillUndocked] = useState(false);
  const [topPillPos, setTopPillPos] = useState<{x: number; y: number}>({ x: 0, y: 0 });
  const topPillDragRef = useRef<{startX: number; startY: number; origX: number; origY: number} | null>(null);
  const topPillPosRef = useRef(topPillPos);
  topPillPosRef.current = topPillPos;
  const topPillUndockedRef = useRef(topPillUndocked);
  topPillUndockedRef.current = topPillUndocked;
  const closeTopPill = useCallback(() => {
    if (topPillUndockedRef.current) return;
    setIsTopPillOpen(false);
  }, []);
  const handleTopPillGrabStart = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    topPillDragRef.current = { startX: clientX, startY: clientY, origX: topPillPosRef.current.x, origY: topPillPosRef.current.y };
    const onMove = (ev: MouseEvent | TouchEvent) => {
      if (!topPillDragRef.current) return;
      const cx = 'touches' in ev ? ev.touches[0].clientX : ev.clientX;
      const cy = 'touches' in ev ? ev.touches[0].clientY : ev.clientY;
      const dx = cx - topPillDragRef.current.startX;
      const dy = cy - topPillDragRef.current.startY;
      if (!topPillUndockedRef.current && Math.abs(dy) > 8) {
        setTopPillUndocked(true);
        setIsTopPillOpen(true);
      }
      setTopPillPos({ x: topPillDragRef.current.origX + dx, y: topPillDragRef.current.origY + dy });
    };
    const onUp = () => {
      topPillDragRef.current = null;
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      document.removeEventListener('touchmove', onMove);
      document.removeEventListener('touchend', onUp);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
    document.addEventListener('touchmove', onMove, { passive: false });
    document.addEventListener('touchend', onUp);
  }, []);
  const redockTopPill = useCallback(() => {
    setTopPillUndocked(false);
    setTopPillPos({ x: 0, y: 0 });
    setIsTopPillOpen(true);
  }, []);
  useEffect(() => {
    if (!isTopPillOpen) return;
    const handleClickOutside = (e: MouseEvent) => {
      if (topPillUndockedRef.current) return;
      const pillEl = topPillRef.current;
      if (pillEl && !pillEl.contains(e.target as Node)) {
        const target = e.target as HTMLElement;
        if (target.closest('[data-tpo]') || target.closest('[data-date-nav]')) return;
        if (target.closest('[role="dialog"]') || target.closest('[data-radix-popper-content-wrapper]') || target.closest('[role="menu"]')) return;
        const triggerAreas = document.querySelectorAll('[data-top-pill-trigger]');
        for (const area of triggerAreas) {
          if (area.contains(target)) return;
        }
        closeTopPill();
      }
    };
    const timer = setTimeout(() => document.addEventListener('click', handleClickOutside), 100);
    return () => { clearTimeout(timer); document.removeEventListener('click', handleClickOutside); };
  }, [isTopPillOpen, closeTopPill]);

