  const refreshFileCounts = useCallback(async (retryCount = 0) => {
    try {
      const response = await fetch('/api/files/counts');
      if (response.ok) {
        const counts = await response.json();
        
        let finalCounts = counts;
        try {
          const odController = new AbortController();
          const odTimeout = setTimeout(() => odController.abort(), 10000);
          const semKeysParam = activeSemKeysRef.current.length > 0 ? `semKeys=${activeSemKeysRef.current.join(',')}` : '';
          const wsdParam = weekStartDateRef.current ? `weekStartDate=${weekStartDateRef.current}` : '';
          const wedParam = weekEndDateRef.current ? `weekEndDate=${weekEndDateRef.current}` : '';
          const qParams = [semKeysParam, wsdParam, wedParam].filter(Boolean).join('&');
          const odResponse = await fetch(`/api/onedrive/week-counts/${selectedWeek}${qParams ? '?' + qParams : ''}`, { signal: odController.signal });
          clearTimeout(odTimeout);
          if (odResponse.ok) {
            const odCounts = await odResponse.json();
            const merged = { ...counts };
            for (const [key, value] of Object.entries(odCounts)) {
              const existing = merged[key] as any;
              const odVal = value as any;
              if (!existing || existing.total === 0) {
                merged[key] = value;
              } else if (odVal && odVal.total > existing.total) {
                merged[key] = { ...existing, total: odVal.total, unlistened: odVal.total - existing.listened };
              }
            }
            finalCounts = merged;
          }
        } catch (odError) {
          if ((odError as any)?.name !== 'AbortError') {
            console.error('Error fetching OneDrive week counts:', odError);
          }
        }
        setFileCounts(finalCounts);
        const legacyCounts: Record<string, number> = {};
        for (const [key, value] of Object.entries(finalCounts)) {
          legacyCounts[key] = (value as { total: number }).total;
        }
        setOneDriveFileCounts(legacyCounts);
      } else if (retryCount < 2) {
        setTimeout(() => refreshFileCounts(retryCount + 1), 1500);
      }
    } catch (error) {
      console.error('Error fetching file counts:', error);
      try { fetch('/api/client-error', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message: `refreshFileCounts error: ${(error as any)?.message || error}`, stack: (error as any)?.stack, userAgent: navigator.userAgent, url: window.location.href, timestamp: new Date().toISOString() }) }).catch(() => {}); } catch {}
      if (retryCount < 2) {
        setTimeout(() => refreshFileCounts(retryCount + 1), 1500);
      }
    }
  }, [selectedWeek]);

