    L2_ECN6: { code: 'CECN210', name: 'Understanding Economics' },
    L2_ECN7: { code: 'ECN220', name: 'Evolution of the Global Economy' },
    L2_ECN8: { code: 'ECN320', name: 'Introduction to Financial Economics' },
