  // OneDrive files for files flyout
  interface OneDriveItem {
    id: string;
    name: string;
    type: "folder" | "file";
    mimeType?: string;
    size?: number;
    lastModified?: string;
    downloadUrl?: string;
    path: string;
  }
  
  const [oneDrivePath, setOneDrivePath] = useState("/School/1. TMU/Courses/2026/Winter");
  const [oneDrivePathHistory, setOneDrivePathHistory] = useState<string[]>([]);
  
  const { data: oneDriveItems = [], isLoading: oneDriveLoading } = useQuery<OneDriveItem[]>({
    queryKey: ["/api/onedrive/files", oneDrivePath],
    queryFn: async () => {
      const response = await fetch(`/api/onedrive/files?path=${encodeURIComponent(oneDrivePath)}`);
      if (!response.ok) {
        const err = await response.json();
        throw new Error(err.error || "Failed to load files");
      }
      return response.json();
    },
  });
  
  const oneDriveFolders = oneDriveItems
    .filter(item => item.type === "folder")
    .sort((a, b) => {
      // Course order to match calendar
      const courseOrder = getKnownCourseCodes();
      
      // Check if folders are course folders
      const getCourseIndex = (name: string) => {
        for (let i = 0; i < courseOrder.length; i++) {
          if (name.includes(courseOrder[i])) return i;
        }
        return -1;
      };
      
      const courseIdxA = getCourseIndex(a.name);
      const courseIdxB = getCourseIndex(b.name);
      
      // If both are course folders, sort by course order
      if (courseIdxA !== -1 && courseIdxB !== -1) {
        return courseIdxA - courseIdxB;
      }
      // Course folders come first
      if (courseIdxA !== -1) return -1;
      if (courseIdxB !== -1) return 1;
      
      // Extract week numbers for chronological sorting
      const weekMatch = (name: string) => {
        const match = name.match(/week\s*(\d+)/i);
        return match ? parseInt(match[1], 10) : null;
      };
      const weekA = weekMatch(a.name);
      const weekB = weekMatch(b.name);
      
      // Current week (week 4 based on semester schedule)
      const currentWeek = 4;
      
      // If both have week numbers, sort with past weeks at bottom
      if (weekA !== null && weekB !== null) {
        const isPastA = weekA < currentWeek;
        const isPastB = weekB < currentWeek;
        
        // If one is past and one is current/future, past goes last
        if (isPastA && !isPastB) return 1;
        if (!isPastA && isPastB) return -1;
        
        // If both are past or both are current/future, sort numerically
        return weekA - weekB;
      }
      // If only one has a week number, put it first
      if (weekA !== null) return -1;
      if (weekB !== null) return 1;
      // Otherwise sort alphabetically
      return a.name.localeCompare(b.name);
    });
  const oneDriveFiles = oneDriveItems.filter(item => item.type === "file");
  const oneDrivePdfFiles = oneDriveFiles.filter(item => item.mimeType?.includes("pdf"));

  // Extract all unique files from tasks for the FILES row
  const allTaskFiles = useMemo(() => {
    const filesMap = new Map<string, { name: string; url: string; taskId: number; courseName: string }>();
    tasks?.forEach(task => {
      if (task.attachments && Array.isArray(task.attachments)) {
        task.attachments.forEach((att: any) => {
          let fileData: { name: string; url: string };
          if (typeof att === 'string') {
            try {
              const parsed = JSON.parse(att);
              fileData = { name: parsed.name || parsed.url?.split('/').pop() || 'File', url: parsed.url || att };
            } catch {
              fileData = { name: att.split('/').pop() || 'File', url: att };
            }
          } else {
            fileData = { name: att.name || att.url?.split('/').pop() || 'File', url: att.url || '' };
          }
          // Try to find matching file in weeklyFiles for displayName
          const matchingWeeklyFile = weeklyFiles.find(wf => wf.objectPath === fileData.url || fileData.url.includes(wf.objectPath));
          if (matchingWeeklyFile) {
            fileData.name = matchingWeeklyFile.displayName || matchingWeeklyFile.originalName || fileData.name;
          }
          const key = fileData.url;
          if (!filesMap.has(key)) {
            filesMap.set(key, { ...fileData, taskId: task.id, courseName: task.courseName || '' });
          }
        });
      }
    });
    return Array.from(filesMap.values());
  }, [tasks, weeklyFiles]);

  // Google Calendar events query
  interface CalendarEvent {
    id: string;
    title: string;
    description: string;
    startDate: string;
    endDate: string;
    isAllDay: boolean;
    htmlLink: string;
    source: string;
  }
  
  const { data: calendarEvents = [] } = useQuery<CalendarEvent[]>({
    queryKey: ["/api/calendar/events", { weekNumber: selectedWeek }],
    queryFn: async () => {
      try {
        const r = await fetch(`/api/calendar/events?weekNumber=${selectedWeek}`, { credentials: 'include' });
        if (!r.ok) throw new Error(r.statusText);
        const data = await r.json();
        if (data && data._deletedTasks) {
          queryClient.invalidateQueries({ queryKey: ["/api/tasks"] });
          return data.events;
        }
        return Array.isArray(data) ? data : (data.events || []);
      } catch { return []; }
    },
    refetchInterval: 5 * 60 * 1000,
    retry: 2,
    retryDelay: 1000,
  });

  const filteredCalendarEvents = useMemo(() => {
    if (authLevel === '1010') return [];
    if (authLevel !== '5747') return [];
    let evs = hiddenCalendarSources.size === 0
      ? calendarEvents
      : calendarEvents.filter((e: any) => {
          const src = (e as any).source || (e as any)._source;
          if (!src) return true;
          return !hiddenCalendarSources.has(src);
        });
    // Dedupe duplicate class events. Two passes:
    //
    // Pass 1 — exact-period dedup. Multiple Google calendars (TMU, primary,
    // secondary) often surface the same class period under slightly
    // different titles (e.g. "CPHL110 - Philosophy of Religion",
    // "PHL 110 - Philosophy of Religion I", "CPHL110 - FA0 - LEC");
    // collapse them by course-code + day + 10-minute start bucket.
    //
    // Pass 2 — per-day collapse. If a single course still has multiple
    // events on the same day at different times (e.g. one source
    // imported the actual 1-4 PM lecture, another guessed at 9-10 AM,
    // another at 12-1 PM — all titled "CPHL110"), keep only the
    // longest one. Bryn's courses don't legitimately meet twice in one
    // day, so the shorter blocks are always stale duplicates.
    //
    // Normalization rules so duplicates actually collide:
    //   • Strip whitespace inside the code (PHL 110 → PHL110).
    //   • Strip a leading "C" before another letter (CPHL110 → PHL110)
    //     so the TMU-prefixed and short forms match.
    const normCode = (raw: string) => {
      const noSpace = raw.replace(/\s+/g, '').toUpperCase();
      return noSpace.replace(/^C(?=[A-Z]{2,})/, '');
    };
    const codeFromTitle = (title: string): string | null => {
      const m = (title || '').toUpperCase().match(/[A-Z]{2,5}\s*\d{3}[A-Z]?/);
      return m ? normCode(m[0]) : null;
    };

    // Pass 1: exact-period dedup.
    const seen = new Set<string>();
    const stage1: any[] = [];
    for (const e of evs) {
      const courseCode = codeFromTitle(e.title);
      if (!courseCode) { stage1.push(e); continue; }
      let key = '';
      try {
        const d = new Date(e.startDate);
        const tenMinBucket = Math.floor(d.getMinutes() / 10);
        key = `${courseCode}|${d.getFullYear()}-${d.getMonth()}-${d.getDate()}|${d.getHours()}:${tenMinBucket}`;
      } catch { stage1.push(e); continue; }
      if (seen.has(key)) continue;
      seen.add(key);
      stage1.push(e);
    }

    // Pass 2: per (course, day) keep longest.
    const byCourseDay = new Map<string, any[]>();
    const passthrough: any[] = [];
    for (const e of stage1) {
      const courseCode = codeFromTitle(e.title);
      if (!courseCode) { passthrough.push(e); continue; }
      let dayKey = '';
      try {
        const d = new Date(e.startDate);
        dayKey = `${courseCode}|${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
      } catch { passthrough.push(e); continue; }
      const arr = byCourseDay.get(dayKey) || [];
      arr.push(e);
      byCourseDay.set(dayKey, arr);
    }
    const out: any[] = [...passthrough];
    for (const arr of byCourseDay.values()) {
      if (arr.length <= 1) { out.push(...arr); continue; }
      // Keep the event with the longest duration; ties broken by earliest start.
      let best = arr[0];
      let bestDur = -1;
      let bestStart = Infinity;
      for (const e of arr) {
        try {
          const s = new Date(e.startDate).getTime();
          const en = new Date(e.endDate || e.startDate).getTime();
          const dur = Math.max(0, en - s);
          if (dur > bestDur || (dur === bestDur && s < bestStart)) {
            best = e; bestDur = dur; bestStart = s;
          }
        } catch {}
      }
      out.push(best);
    }
    return out;
  }, [calendarEvents, authLevel, hiddenCalendarSources]);

