  // File preview dialog state
  const [previewFile, setPreviewFile] = useState<FileItem | null>(null);
  const previewFileRef = useRef<FileItem | null>(null);
  const [oneDrivePreviewFiles, setOneDrivePreviewFiles] = useState<FileItem[]>([]);
