          <div className="alert-bar-shimmer" style={{ position: 'fixed', top: '37px', left: 'calc(50% + 63px + 35px)', right: 0, height: '3px', backgroundColor: '#ff0000', zIndex: 112, pointerEvents: 'none', animationDelay: '0.3s' }} />
