                        <div style={{ display: 'flex', width: '100%', height: '22px', flexShrink: 0 }}>
                          <div style={{ width: '50%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', borderRight: `1.5px solid ${labelBorderColor}`, borderBottom: `1.5px solid ${labelBorderColor}`, boxSizing: 'border-box' }} className="hover:brightness-125" onClick={async (e) => { e.stopPropagation(); const code = courseData.name.split(' - ')[0]?.trim(); if (syncingCourses.has(code)) return; setSyncResults(prev => { const n = new Map(prev); n.delete(code); return n; }); setSyncingCourses(prev => new Set(prev).add(code)); try { const resp = await fetch('/api/onedrive/sync-course-week', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ courseCode: code, weekNumber: selectedWeek, semKey: courseData._semKey, weekStartDate: weekStartDate.toISOString(), weekEndDate: weekEndDate.toISOString() }) }); const data = await resp.json(); console.log('[Sync Debug]', code, 'week', selectedWeek, data); queryClient.invalidateQueries({ queryKey: ['/api/files'] }); queryClient.invalidateQueries({ queryKey: ['/api/files/counts'] }); refreshFileCounts(); const count = data?.synced?.length || 0; const skipped = data?.skippedExisting || 0; setSyncResults(prev => new Map(prev).set(code, { count, skipped, message: data?.message })); setTimeout(() => setSyncResults(prev => { const n = new Map(prev); n.delete(code); return n; }), 5000); } catch (e2) { console.error('Sync failed:', e2); setSyncResults(prev => new Map(prev).set(code, { count: -1 })); setTimeout(() => setSyncResults(prev => { const n = new Map(prev); n.delete(code); return n; }), 3000); } finally { setSyncingCourses(prev => { const n = new Set(prev); n.delete(code); return n; }); } }} data-testid={`btn-sync-${course.name}`}><svg viewBox="0 0 24 24" fill="none" stroke={labelIconColor} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ width: '18px', height: '18px' }}><path d="M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z" /></svg></div>
                          <div style={{ width: '50%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', borderBottom: `1.5px solid ${labelBorderColor}`, boxSizing: 'border-box' }} className="hover:brightness-125" onClick={async (e) => { e.stopPropagation(); const code = courseData.name.split(' - ')[0]?.trim(); if (!window.confirm(`Are you sure you want to reset files for ${code} Week ${selectedWeek}?`)) return; try { const resp = await fetch('/api/reset-course-week-files', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ courseCode: code, weekNumber: selectedWeek }) }); const data = await resp.json(); queryClient.invalidateQueries({ queryKey: ['/api/files'] }); queryClient.invalidateQueries({ queryKey: ['/api/files/counts'] }); refreshFileCounts(); setSyncResults(prev => new Map(prev).set(code, { count: data.resetCount ?? 0 })); setTimeout(() => setSyncResults(prev => { const n = new Map(prev); n.delete(code); return n; }), 3000); } catch (e2) { console.error('Reset failed:', e2); } }} data-testid={`btn-reset-${course.name}`}><svg viewBox="0 0 24 24" fill="none" stroke={labelIconColor} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ width: '14px', height: '14px' }}><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" /><path d="M3 3v5h5" /></svg></div>
                        </div>
